import React from "react";
import { Link } from "react-router-dom";
import { ArrowRight, BarChart3, CalendarDays, ShieldCheck, Sparkles, Users, GraduationCap } from "lucide-react";
import Logo from "../components/common/Logo";

export default function LandingPage() {
  return <div className="landing"><header className="landing-nav"><Logo /><nav><a href="#features">Features</a><a href="#about">About</a><Link to="/login" className="btn btn-outline btn-sm">Sign in</Link></nav></header><section className="hero"><div className="hero-copy"><span className="eyebrow"><Sparkles size={15}/> Smart school management</span><h1>Everything your school needs, <span>in one flow.</span></h1><p>EduFlow helps administrators, teachers and parents manage students, academics, attendance, payments and communication from one modern dashboard.</p><div className="hero-actions"><Link to="/login" className="btn btn-primary btn-lg">Get started <ArrowRight size={18}/></Link><a href="#features" className="btn btn-ghost btn-lg">Explore features</a></div></div><div className="hero-dashboard"><div className="mock-top"><span>EduFlow Dashboard</span><span className="live">● Live</span></div><div className="mock-stats"><div><small>Students</small><b>1,248</b><span>+8.2%</span></div><div><small>Attendance</small><b>94.6%</b><span>+2.1%</span></div><div><small>Performance</small><b>87.4%</b><span>+5.8%</span></div></div><div className="mock-chart"><div className="bars">{[40,58,48,72,64,88,76,95].map((h,i)=><i style={{height:`${h}%`}} key={i}/>)}</div></div></div></section><section id="features" className="feature-section"><div className="section-title"><span className="eyebrow">Powerful features</span><h2>Built for the whole school</h2><p>Simple tools that keep everyone aligned and informed.</p></div><div className="feature-grid">{[[Users,"Student management","Create, search and track every student from one place."],[BarChart3,"Academic insights","See performance and attendance trends at a glance."],[CalendarDays,"Schedules & events","Keep exams, meetings and school events organized."],[ShieldCheck,"Secure access","Separate admin and parent experiences with clean permissions."]].map(([Icon,title,desc])=><div className="feature-card" key={title}><div><Icon size={22}/></div><h3>{title}</h3><p>{desc}</p></div>)}</div></section><section id="about" className="cta"><GraduationCap size={32}/><h2>Ready to simplify your school?</h2><p>Start with the demo dashboard and explore EduFlow.</p><Link to="/login" className="btn btn-primary">Open EduFlow <ArrowRight size={17}/></Link></section><footer>© 2026 EduFlow Student Management System</footer></div>;
}
